SELECT 
FROM team t
JOIN user_account leader ON leader.user_id = t.leader_user_id
LEFT JOIN region rg ON rg.region_id = t.region_id
WHERE 1 = 1

    AND (
      t.name LIKE CONCAT('%', #{keyword}, '%')
      OR t.description LIKE CONCAT('%', #{keyword}, '%')
      OR leader.nickname LIKE CONCAT('%', #{keyword}, '%')
    )


    AND t.status = #{status}


    AND t.region_id = #{regionId}


    AND t.leader_user_id = #{leaderUserId}

ORDER BY t.updated_at DESC, t.last_active_at DESC, t.created_at DESC
LIMIT #{limit}

