UPDATE team_member
SET team_role = #{teamRole}
WHERE team_id = #{teamId}
  AND user_id = #{userId}
  AND status = 'ACTIVE'

UPDATE team_member
SET status = #{status},
    left_at = NOW()
WHERE team_id = #{teamId}
  AND user_id = #{userId}
  AND status = 'ACTIVE'

UPDATE team
SET current_member_count = (
      SELECT COUNT(*)
      FROM team_member
      WHERE team_id = #{teamId}
        AND status = 'ACTIVE'
    ),
    last_active_at = NOW(),
    updated_at = NOW()
WHERE team_id = #{teamId}

UPDATE team_recruitment
SET status = #{status},
    updated_at = NOW()
WHERE team_id = #{teamId}
  AND recruitment_id = #{recruitmentId}
  AND status != 'DELETED'

UPDATE team_recruitment
SET status = #{status},
    updated_at = NOW()
WHERE team_id = #{teamId}
  AND recruitment_id = #{recruitmentId}

