UPDATE team_recruitment_slot s
JOIN team_recruitment r ON r.recruitment_id = s.recruitment_id
SET s.status = #{status},
    s.updated_at = NOW()
WHERE r.team_id = #{teamId}
  AND s.slot_id = #{slotId}

